FROM (
        SELECT
            patient_id,
            CAST(effective_datetime AS date) as date,
            CAST(snomed_concept_id AS varchar) AS snomedct_code,
            CAST(numeric_value AS real) AS numeric_value,
            consultation_id
        FROM observation
        ) AS clinical_events 
WHERE clinical_events.date >= '2023-11-01' AND clinical_events.date <= '2023-11-30' AND clinical_events.snomedct_code IN ('983341000000102', '2129921000000100', '1577041000000109');

-- Run query 002 / 720
-- project_id=POS-YYYY-XXXX workspace_id=a-project-workspace job_id=a1b2c3d4e5f6g7
CREATE TABLE ehrql_20261026_1923_fae5e6bb23a2_tmp_1 AS SELECT anon_1.patient_id AS patient_id 
FROM (SELECT practice_registrations.patient_id AS patient_id, row_number() OVER (PARTITION BY practice_registrations.patient_id ORDER BY practice_registrations.start_date DESC) AS anon_2 
FROM (
        SELECT
            patient_id AS patient_id,
            CAST(registration_start_datetime AS date) AS start_date,
            CAST(registration_end_datetime AS date) AS end_date
        FROM patient
        ) AS practice_registrations 
WHERE practice_registrations.start_date <= '2023-11-30' AND (practice_registrations.end_date >= '2023-11-30' OR practice_registrations.end_date IS NULL)) AS anon_1 
WHERE anon_1.anon_2 = 1;

-- Run query 003 / 720
-- project_id=POS-YYYY-XXXX workspace_id=a-project-workspace job_id=a1b2c3d4e5f6g7
CREATE TABLE ehrql_20261026_1923_fae5e6bb23a2_tmp_3 AS SELECT ehrql_20261026_1923_fae5e6bb23a2_tmp_1.patient_id AS patient_id 
FROM ehrql_20261026_1923_fae5e6bb23a2_tmp_1 UNION SELECT patients.patient_id AS patient_id 
FROM (
        SELECT
            patient_id AS patient_id,
            CAST(date_of_birth AS date) AS date_of_birth,
            CASE
                WHEN sex = 'M' THEN 'male'
                WHEN sex = 'F' THEN 'female'
                WHEN sex = 'I' THEN 'intersex'
                ELSE 'unknown'
            END AS sex,
            CAST(date_of_death AS date) AS date_of_death
        FROM patient
        ) AS patients UNION SELECT ehrql_20261026_1923_fae5e6bb23a2_tmp_2.patient_id AS patient_id 
FROM ehrql_20261026_1923_fae5e6bb23a2_tmp_2 UNION SELECT t1oo.patient_id AS patient_id 
FROM (
        SELECT
            patient_id
        FROM patient
        WHERE
            is_consent_9nu0 = false
        ) AS t1oo UNION SELECT ndoo.patient_id AS patient_id 
FROM (
        SELECT
            patient_id
        FROM patient
        WHERE
            is_national_data_opted_in = false
        ) AS ndoo;

