FROM (
        SELECT
            patient_id,
            CAST(effective_datetime AS date) as date,
            CAST(snomed_concept_id AS varchar) AS snomedct_code,
            CAST(numeric_value AS real) AS numeric_value,
            consultation_id
        FROM observation
        ) AS clinical_events 
WHERE clinical_events.date >= '2024-11-01' AND clinical_events.date <= '2024-11-30' AND clinical_events.snomedct_code IN ('983341000000102', '2129921000000100', '1577041000000109');

