CREATE TABLE ehrql_20261026_1923_fae5e6bb23a2_tmp_333 AS SELECT clinical_events.patient_id AS patient_id, COUNT(DISTINCT clinical_events.consultation_id) AS value 
FROM (
        SELECT
            patient_id,
            CAST(effective_datetime AS date) as date,
            CAST(snomed_concept_id AS varchar) AS snomedct_code,
            CAST(numeric_value AS real) AS numeric_value,
            consultation_id
        FROM observation
        ) AS clinical_events 
WHERE clinical_events.date >= '2025-01-01' AND clinical_events.date <= '2025-01-31' AND clinical_events.consultation_id IN (SELECT ehrql_20261026_1923_fae5e6bb23a2_tmp_329.value 
FROM ehrql_20261026_1923_fae5e6bb23a2_tmp_329 
WHERE ehrql_20261026_1923_fae5e6bb23a2_tmp_329.patient_id = clinical_events.patient_id) AND clinical_events.snomedct_code IN ('3110003', '48277006', '4740000', '262550002', '1090711000000102', '15805002', '363746003') AND (clinical_events.consultation_id NOT IN (SELECT ehrql_20261026_1923_fae5e6bb23a2_tmp_332.value 
FROM ehrql_20261026_1923_fae5e6bb23a2_tmp_332 
WHERE ehrql_20261026_1923_fae5e6bb23a2_tmp_332.patient_id = clinical_events.patient_id)) AND clinical_events.patient_id IN (SELECT ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id 
FROM ehrql_20261026_1923_fae5e6bb23a2_tmp_326) GROUP BY clinical_events.patient_id;

