CREATE TABLE ehrql_20261026_1923_fae5e6bb23a2_tmp_345 AS SELECT ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id AS patient_id, CAST(CASE WHEN (ehrql_20261026_1923_fae5e6bb23a2_tmp_323.patient_id IS NOT NULL AND patients.sex IN ('male', 'female') AND ehrql_20261026_1923_fae5e6bb23a2_tmp_324.patient_id IS NOT NULL) THEN true WHEN (NOT (ehrql_20261026_1923_fae5e6bb23a2_tmp_323.patient_id IS NOT NULL AND patients.sex IN ('male', 'female') AND ehrql_20261026_1923_fae5e6bb23a2_tmp_324.patient_id IS NOT NULL)) THEN false END AS INTEGER) AS column_0, coalesce(ehrql_20261026_1923_fae5e6bb23a2_tmp_331.value, 0) AS column_1, coalesce(ehrql_20261026_1923_fae5e6bb23a2_tmp_333.value, 0) AS column_2, coalesce(ehrql_20261026_1923_fae5e6bb23a2_tmp_334.value, 0) AS column_3, coalesce(ehrql_20261026_1923_fae5e6bb23a2_tmp_338.value, 0) AS column_4, coalesce(ehrql_20261026_1923_fae5e6bb23a2_tmp_340.value, 0) AS column_5, coalesce(ehrql_20261026_1923_fae5e6bb23a2_tmp_341.value, 0) AS column_6, coalesce(ehrql_20261026_1923_fae5e6bb23a2_tmp_342.value, 0) AS column_7, coalesce(ehrql_20261026_1923_fae5e6bb23a2_tmp_343.value, 0) AS column_8, coalesce(ehrql_20261026_1923_fae5e6bb23a2_tmp_344.value, 0) AS column_9 
FROM ehrql_20261026_1923_fae5e6bb23a2_tmp_326 LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_323 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_323.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN (
        SELECT
            patient_id AS patient_id,
            CAST(date_of_birth AS date) AS date_of_birth,
            CASE
                WHEN sex = 'M' THEN 'male'
                WHEN sex = 'F' THEN 'female'
                WHEN sex = 'I' THEN 'intersex'
                ELSE 'unknown'
            END AS sex,
            CAST(date_of_death AS date) AS date_of_death
        FROM patient
        ) AS patients ON patients.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_324 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_324.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_331 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_331.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_333 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_333.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_334 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_334.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_338 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_338.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_340 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_340.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_341 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_341.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_342 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_342.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_343 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_343.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id LEFT OUTER JOIN ehrql_20261026_1923_fae5e6bb23a2_tmp_344 ON ehrql_20261026_1923_fae5e6bb23a2_tmp_344.patient_id = ehrql_20261026_1923_fae5e6bb23a2_tmp_326.patient_id;

